def transform(grid):
    """Overlay the two binary panels; mark cells occupied in both with 2."""
    h, w = len(grid), len(grid[0])
    # Find a uniform, nonzero separator row or column.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom) and top:
                return [[2 if a != 0 and b != 0 else 0
                         for a, b in zip(ra, rb)]
                        for ra, rb in zip(top, bottom)]
    for c in range(w):
        if grid[0][c] != 0 and all(row[c] == grid[0][c] for row in grid):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if all(len(a) == len(b) for a, b in zip(left, right)) and left and len(left[0]) == len(right[0]):
                return [[2 if a != 0 and b != 0 else 0
                         for a, b in zip(ra, rb)]
                        for ra, rb in zip(left, right)]
    raise ValueError('No balanced uniform separator found')
